{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Esaxerenone, a close analogue sharing the methylsulfonylphenyl and heteroaryl motifs, had an absolute oral bioavailability of 89.0% in healthy Japanese subjects in the fasting state, directly matching the endpoint and condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Basmisanil, a heteroaryl-containing analogue, showed approximately 75% absolute oral bioavailability in humans, supporting high F for structurally related compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Imatinib, which shares heteroaromatic and polar substituent features, had a mean absolute bioavailability of 97.2% versus IV infusion in patients, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Odanacatib, a methylsulfonylbiphenyl-containing analogue, had 30% absolute oral bioavailability in the fasted state at a 50 mg dose; although the lowest among close analogues, it still exceeds the 20% threshold and supports a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "BI 425809, which contains a methylsulfonylphenyl group and heteroaryl/CF3 features similar to the query, had 71.64% absolute oral bioavailability from a fasted 25 mg tablet in healthy participants.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Imatinib was rapidly and completely absorbed with a mean absolute bioavailability of 98%, independent of food intake, providing additional high-transfer support for high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer analogues with direct human absolute bioavailability measurements show F values from 30% to 98%, all above the 20% threshold; the query's methylsulfonylphenyl/heteroaryl structure aligns with these high-bioavailability compounds, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability measurement exists for the exact query molecule; the prediction relies on close structural analogues.",
    "Odanacatib shows dose-dependent absorption (30% at 50 mg vs 70% at 10 mg), and the query dose is unspecified; however, even the lower value exceeds the 20% threshold."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "methylsulfonylphenyl heteroaryl high-F analogues"
    }
  ],
  "revision_action": "initial"
}

